package ru.kryuch.krtg.searcher.helper;import jakarta.transaction.Transactional;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import ru.kryuch.krtg.searcher.dto.TgUserAvatar;import ru.kryuch.krtg.searcher.entity.TgUserEntity;import ru.kryuch.krtg.searcher.repository.TgUserRepository;import java.util.Optional;@Component@RequiredArgsConstructorpublic class TgUserHelper {	private final TgUserRepository tgUserRepository;	public Optional <String> getAvatar(Long tgUserId) {		Optional<TgUserEntity> tgUser = tgUserRepository.findById(tgUserId);		if (tgUser.isPresent() && tgUser.get().getAvatar() != null) {			return Optional.of(tgUser.get().getAvatar());		}		return Optional.empty();	}	@Transactional	public void updateAvatar(TgUserAvatar avatar) {		Optional<TgUserEntity> tgUser = tgUserRepository.findById(avatar.getKey().getUserId());		if (tgUser.isPresent()) {			tgUser.get().setAvatar(avatar.getValue());			tgUserRepository.save(tgUser.get());		}	}}